/**
 * Help: the searchable list of every feature and where to find it (src/design/logic/help.js, data generated by tools/gen_help.py).
 *
 * The data ships with the app, so searching makes no request and no broker call; the harness fails any spec that leaves the origin or
 * trips the Content-Security-Policy.  The existing short sections stay for an empty box; a query replaces them with the matching topics.
 */
import { expect, test, type App } from "./harness";
import { HELP_FEATURES } from "../../src/design/logic/help-data.js";

const TOTAL = HELP_FEATURES.length;

async function openHelp(app: App) {
  const broker = (await app.open({ broker: { locked: false } }))!;
  await expect(app.screen("S1 Main")).toBeVisible();
  await app.page.getByRole("button", { name: "help", exact: true }).click();
  await expect(app.screen("S21 Help")).toBeVisible();
  return broker;
}

const help = (app: App) => app.screen("S21 Help");
const box = (app: App) => help(app).getByRole("searchbox", { name: "search help topics" });
const count = (app: App) => help(app).locator('[data-help-count="true"]');
const topics = (app: App) => help(app).locator('[data-help-topic="true"]');

test("Help opens on a labelled search box, the short sections and the whole list, and announces the count", async ({ app }) => {
  await openHelp(app);
  await expect(box(app)).toBeVisible();
  await expect(box(app)).toBeFocused(); // keyboard users land in the box
  await expect(count(app)).toHaveText(`${TOTAL} topics`);
  await expect(count(app)).toHaveAttribute("role", "status"); // a screen reader hears the count change
  await expect(count(app)).toHaveAttribute("aria-live", "polite");
  await expect(topics(app)).toHaveCount(TOTAL);
  // the short sections that were always there are still there
  await expect(help(app)).toContainText("reading the graph");
  await expect(help(app)).toContainText("writing while locked");
  await expect(help(app)).toContainText("needs presence (Touch ID), which this beta cannot attest yet");
  // each topic shows its title, where it is and what it does
  const first = topics(app).first();
  await expect(first).toContainText("Create the vault: choose a passphrase");
  await expect(first).toContainText("Where: App: first run, step 1 of 4");
  await expect(first).toContainText("The first time the app starts with no vault");
});

test("typing filters the list live, ranks a title match first, and hides the short sections", async ({ app }) => {
  await openHelp(app);
  await box(app).fill("backup");
  await expect(count(app)).toContainText(`of ${TOTAL} topics match`);
  await expect(count(app)).toContainText("backup");
  const n = Number(/^(\d+) of /.exec((await count(app).innerText()) ?? "")?.[1]);
  expect(n).toBeGreaterThan(2);
  expect(n).toBeLessThan(TOTAL);
  await expect(topics(app)).toHaveCount(n); // the announced number is the number shown
  await expect(topics(app).first()).toContainText("Backup retention"); // a title match outranks one that only has the word in its search terms
  await expect(topics(app).filter({ hasText: "Back up the vault" })).toHaveCount(1); // found through its search terms
  await expect(help(app)).not.toContainText("reading the graph"); // the short sections give way to the results
  await expect(help(app)).not.toContainText("Shortcut: T toggle graph and tree");

  // every word must match, in any order
  await box(app).fill("vault back");
  await expect(topics(app).filter({ hasText: "Back up the vault" })).toHaveCount(1);
  await box(app).fill("RECOVERY   code");
  await expect(topics(app).first()).toContainText("Recovery code, shown once");

  // a synonym that appears only in the search terms still finds the topic
  await box(app).fill("yubikey");
  await expect(topics(app)).toHaveCount(1);
  await expect(topics(app).first()).toContainText("Security-key second factor");
});

test("a topic that does not exist yet says so, and a search with no match says so and can be cleared", async ({ app }) => {
  await openHelp(app);
  await box(app).fill("touch id");
  const row = topics(app).filter({ hasText: "Touch ID and presence checks" });
  await expect(row).toHaveCount(1);
  await expect(row).toContainText("planned"); // the badge says it is not there yet

  await box(app).fill("zzzxqj");
  await expect(topics(app)).toHaveCount(0);
  await expect(count(app)).toHaveText("No topic matches “zzzxqj”");
  await expect(help(app)).toContainText("Nothing matches.");
  await help(app).getByRole("button", { name: "Clear" }).click();
  await expect(box(app)).toHaveValue("");
  await expect(count(app)).toHaveText(`${TOTAL} topics`);
  await expect(topics(app)).toHaveCount(TOTAL);
  await expect(help(app)).toContainText("reading the graph");
});

test("typing a shortcut letter into the box does not trigger the shortcut, and Esc closes Help", async ({ app }) => {
  await openHelp(app);
  await box(app).fill("");
  await box(app).pressSequentially("fgtne");
  await expect(box(app)).toHaveValue("fgtne");
  expect(await app.page.evaluate(() => (window as any).__cm.state.view)).toBe("graph"); // T did not switch to the tree
  expect(await app.page.evaluate(() => (window as any).__cm.state.dialog)).toBe("help"); // N did not open Add entry
  await app.page.keyboard.press("Escape");
  await expect(help(app)).toHaveCount(0);
});

test("searching is local: it makes no broker call and keeps nothing in storage", async ({ app }) => {
  const broker = await openHelp(app);
  const before = (await broker.calls()).length;
  const storageBefore = await app.storageDump();
  await box(app).fill("agent approval");
  await expect(topics(app).first()).toBeVisible();
  await expect(topics(app).filter({ has: app.page.getByText("Decide an agent's waiting request", { exact: true }) })).toHaveCount(1);
  await expect(help(app)).toContainText("credmgr approve <request>");
  expect((await broker.calls()).length).toBe(before);
  expect(await app.storageDump()).toBe(storageBefore); // the query is page state only
});

test("every topic names a place, and no topic claims what the app cannot do", async ({ app }) => {
  await openHelp(app);
  const text = (await help(app).innerText()).toLowerCase();
  for (const bad of ["settings → agents", "touch id and a fresh 2fa", "deliberate friction", "settings → nodes lists everything", "not built", "mock"]) expect(text, bad).not.toContain(bad);
  const rows = await topics(app).count();
  expect(rows).toBe(TOTAL);
  for (const f of HELP_FEATURES) expect(f.where.length, f.id).toBeGreaterThan(5);
});
